const result = $input.first().json.stdout;
if (!result) return [];
const lines = result.split('\n').filter(l => l.trim() !== '');
const EXT = /\.(jpg|jpeg|png|webp|gif)$/i;

function normalizeName(str) {
  if (!str) return '';
  return String(str).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]/g, '');
}

const out = [];
for (const fullPath of lines) {
  if (!EXT.test(fullPath)) continue;

  const parts = fullPath.split('/');
  const fileName = parts.pop();
  const categoryRaw = parts.pop();

  if (!categoryRaw) continue;

  const category = normalizeName(categoryRaw);
  const baseName = fileName.replace(/\.[^.]+$/i, '');
  const matchKey = normalizeName(baseName);
  const compositeKey = matchKey + '|' + category;

  out.push({ 
    json: { 
      path: fullPath, 
      fileName, 
      categoryRaw, 
      category, 
      matchKey, 
      compositeKey 
    } 
  });
}

return out;

const items = $input.all();
const cleaned = [];

const COL = { 
  codigo: 'CÓDIGO', 
  nombre: 'NOMBRE', 
  precioUsd: 'PRECIO USD', 
  precioCup: 'PRECIO CUP', 
  estado: 'ESTADO' 
};

function safeNum(val) {
  if (val === null || val === undefined) return null;
  if (typeof val === 'number' && !Number.isNaN(val)) return val;
  const s = String(val).replace(/[^0-9.,]/g, '').replace(',', '.');
  const n = parseFloat(s);
  return Number.isNaN(n) ? null : n;
}

function safeStr(val) {
  if (val === null || val === undefined) return '';
  return String(val).trim();
}

function normalizeName(str) {
  if (!str) return '';
  return String(str).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function isSectionHeader(codigo, nombre) {
  const c = String(codigo).trim();
  const n = safeStr(nombre);
  return c.includes('---') || (!n && !c);
}

function sectionToCategory(codigo) {
  const m = String(codigo).match(/---\s*([^---]+)\s*---/);
  return m ? normalizeName(m[1]) : null;
}

let currentCategory = '';

for (const item of items) {
  const row = item.json || item;

  const codigoRaw = row[COL.codigo];
  const nombre = safeStr(row[COL.nombre]);
  const usd = safeNum(row[COL.precioUsd]);
  const cup = safeNum(row[COL.precioCup]);

  if (isSectionHeader(codigoRaw, nombre)) {
    const cat = sectionToCategory(codigoRaw);
    if (cat) currentCategory = cat;
    continue;
  }

  if (!nombre) continue;

  const matchKey = normalizeName(nombre);
  if (!matchKey) continue;

  const category = currentCategory || 'GENERAL';
  const compositeKey = matchKey + '|' + category;

  cleaned.push({
    json: {
      matchKey,
      category,
      compositeKey,
      codigo: codigoRaw,
      productId: nombre,
      usdPrice: usd,
      cupPrice: cup,
      usdFormatted: usd != null ? `$${Number(usd).toFixed(2)} USD` : '',
      cupFormatted: cup != null ? `${Number(cup).toLocaleString('en-US')} CUP` : ''
    }
  });
}

return cleaned;

const fs = require('fs');
const originalData = $('LoopNode').first().json;

// Gemini's text output might be nested since we removed the simplify restriction
// We try different possible paths just in case to avoid 'undefined'
const geminiData = $input.first().json;
let geminiText = '🚨 Visítanos antes que se agoten 🚨';

if (geminiData.content && geminiData.content.parts && geminiData.content.parts.length > 0) {
    geminiText = geminiData.content.parts[0].text;
} else if (geminiData.text) {
    geminiText = geminiData.text;
} else if (geminiData.message && geminiData.message.content) {
    geminiText = geminiData.message.content;
}

const productoPath = originalData.path;
const logoPath = '/data/logo2.jpeg';

if (!productoPath) {
  throw new Error('path is missing from LoopNode. Keys: ' + JSON.stringify(Object.keys(originalData)));
}

const productoBuffer = fs.readFileSync(productoPath);
const logoBuffer = fs.readFileSync(logoPath);

const ext = productoPath.split('.').pop().toLowerCase();
const mimeMap = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif' };
const productoMime = mimeMap[ext] || 'image/jpeg';

return [{
  json: {
    ...originalData,
    logoBase64: logoBuffer.toString('base64'),
    logoMime: 'image/jpeg',
    productoBase64: productoBuffer.toString('base64'),
    productoMime,
    copyText: geminiText
  }
}];

