=<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body, html {
            width: 1080px;
            height: 1080px;
            overflow: hidden;
            background: linear-gradient(170deg, #6d1e68 0%, #4a1547 100%);
            font-family: 'Arial Black', 'Arial Bold', Arial, sans-serif;
        }
        .layout { width: 1080px; height: 1080px; display: flex; flex-direction: column; }

        .header { height: 180px; display: flex; align-items: center; padding: 0 55px; justify-content: flex-start; }
        .logo { height: 130px; width: 130px; object-fit: cover; border-radius: 50%; box-shadow: 0px 8px 15px rgba(0,0,0,0.5); }

        .product-zone { 
            flex: 1; 
            display: flex; 
            justify-content: center; 
            align-items: center; 
            padding: 10px 40px; 
        }

        .product-img { 
            width: 100%; 
            height: 100%; 
            max-height: 560px; /* Reducimos 40px aquí para darle más espacio al info-zone de abajo */
            object-fit: contain; 
            filter: drop-shadow(0px 15px 25px rgba(0,0,0,0.4));
        }

        .info-zone { 
            height: 340px; /* Aumentado 40px para más aire */
            background: #ffffff; 
            border-top: 6px solid #6d1e68; 
            padding: 30px 40px; 
            display: flex; 
            flex-direction: column; 
            justify-content: center; 
            align-items: center; 
            gap: 25px; /* AUMENTO SIGNIFICATIVO DEL GAP (Separación entre lineas) */
            text-align: center;
        }

        .product-name { 
            font-size: 38px; 
            font-weight: 800; 
            color: #222222; 
            text-transform: uppercase; 
            line-height: 1.1; 
            letter-spacing: 0.5px;
        }

        .price-row { 
            display: flex; 
            align-items: baseline; 
            justify-content: center; 
            gap: 15px; 
        }

        /* Precios en unaSola linea unificados en tamaño */
        .price-val { font-size: 55px; font-weight: 800; color: #e87b04; line-height: 1; letter-spacing: -1px; }
        .price-separator { font-size: 50px; font-weight: 300; color: #aaaaaa; margin: 0 5px; }

        /* Uso fuente especial para emojis si es necesario */
        .cta { 
            font-size: 26px; 
            font-weight: 800; 
            background: linear-gradient(90deg, #BF953F, #FCF6BA, #B38728, #FBF5B7, #AA771C);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
            text-transform: uppercase; 
            letter-spacing: 0.5px; 
            line-height: 1.2; 
            padding: 0 10px;
            font-family: 'Arial Black', "Noto Color Emoji", sans-serif;
        }
    </style>
</head>
<body>
    <div class="layout">
        <div class="header">
            <img src="data:{{ $json.logoMime }};base64,{{ $json.logoBase64 }}" class="logo" />
        </div>
        <div class="product-zone">
            <img src="data:{{ $json.productoMime }};base64,{{ $json.productoBase64 }}" class="product-img" />
        </div>
        <div class="info-zone">
            <div class="product-name">{{ $json.productId }}</div>
            <div class="price-row">
                <span class="price-val">{{ $json.cupPrice }} CUP</span>
                <span class="price-separator">/</span>
                <span class="price-val">{{ $json.usdPrice }} USD</span>
            </div>
            <div class="cta">{{ $json.copyText }}</div>
        </div>
    </div>
</body>
</html>
